import sys
from collections import defaultdict

def is_balanced(sequence):
    balance = 0
    for num in sequence:
        if num > 0:
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    cards = [(int(input[2*i+1]), int(input[2*i+2])) for i in range(n)]

    front_counts = defaultdict(int)
    back_counts = defaultdict(int)
    for a, b in cards:
        front_counts[a] += 1
        back_counts[b] += 1

    if any(count != 1 for count in front_counts.values()) or any(count != 1 for count in back_counts.values()):
        print("NO")
        return

    def dfs(node, visited, path, front_used, back_used):
        if node in visited:
            return False
        visited.add(node)
        path.append(node)
        if node > 0:
            if front_used[node]:
                return False
            front_used[node] = True
            for a, b in cards:
                if a == node and not back_used[b]:
                    if dfs(b, visited, path, front_used, back_used):
                        return True
        else:
            if back_used[node]:
                return False
            back_used[node] = True
            for a, b in cards:
               	if b == node and not front_used[a]:
                    if dfs(a, visited, path, front_used, back_used):
                        return True
            path.pop()
            back_used[node] = False
        return len(path) == 2 * n

    path = []
    front_used = defaultdict(bool)
    back_used = defaultdict(bool)
    for i in range(1, n + 1):
        if not front_used[i]:
            if not dfs(i, set(), path, front_used, back_used):
                print("NO")
                return

    if is_balanced(path) and is_balanced([-x for x in path]):
        print("YES")
        for num in path:
            for a, b in cards:
                if a == num:
                    print(a, b)
                    break
    else:
        print("NO")

if __name__ == "__main__":
    main()
